// ---- shared command parser (kept identical in both parser nodes) ----
const HELP = [
  '<b>🤖 AutoGenie lead bot</b>',
  '',
  '<b>Usage</b>',
  '<code>/leads plumbers in Chicago, IL</code>',
  '<code>/leads dentists | Austin, TX --limit 30 --no-website</code>',
  '',
  '<b>Flags</b>',
  '<code>--limit N</code>  number of NEW leads (default ' + ($env.DEFAULT_LEAD_LIMIT || 20) + ', max 100)',
  '<code>--phone</code>  only leads with a phone number',
  '<code>--has-website</code> / <code>--no-website</code>',
  '<code>--min-rating 4.2</code>   <code>--max-rating 4</code>   <code>--min-reviews 10</code>',
  '<code>--emails</code>  look for emails on their websites (slower)',
  '<code>--all</code>  include leads that were already sent before',
  '',
  'Leads already delivered are skipped automatically, so you can repeat a search to get fresh ones.',
].join('\n');

function escapeHtml(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function parseJob(input, defaultLimit) {
  let text = ' ' + String(input || '').replace(/[–—]{1}/g, '--') + ' ';
  const filters = {};
  let limit = defaultLimit, emails = false, all = false;

  const num = (re) => {
    const m = text.match(re);
    if (!m) return null;
    text = text.replace(m[0], ' ');
    return Number(m[1]);
  };
  const flag = (re) => {
    if (!re.test(text)) return false;
    text = text.replace(re, ' ');
    return true;
  };

  const l = num(/\s(?:--limit|-n)\s*=?\s*(\d+)/i);            if (l) limit = l;
  const minR = num(/\s--min-rating\s*=?\s*([\d.]+)/i);        if (minR != null) filters.min_rating = minR;
  const maxR = num(/\s--max-rating\s*=?\s*([\d.]+)/i);        if (maxR != null) filters.max_rating = maxR;
  const minRev = num(/\s--min-reviews\s*=?\s*(\d+)/i);        if (minRev != null) filters.min_reviews = minRev;
  if (flag(/\s--no-website(?=\s)/i)) filters.without_website = true;
  if (flag(/\s--has-website(?=\s)/i)) filters.require_website = true;
  if (flag(/\s--phone(?=\s)/i)) filters.require_phone = true;
  if (flag(/\s--closed(?=\s)/i)) filters.include_closed = true;
  if (flag(/\s--emails?(?=\s)/i)) emails = true;
  if (flag(/\s--all(?=\s)/i)) all = true;

  const unknown = text.match(/\s(--?[a-z][\w-]*)/i);
  if (unknown) return { error: 'Unknown flag: <code>' + escapeHtml(unknown[1]) + '</code>' };
  if (filters.without_website && filters.require_website)
    return { error: '--no-website and --has-website cannot be combined.' };

  text = text.replace(/\s+/g, ' ').trim();
  let niche = text, location = null;
  if (text.includes('|')) {
    [niche, location] = text.split('|').map((s) => s.trim());
  } else {
    const m = text.match(/^(.+)\s+(?:in|near|around)\s+(.+)$/i);
    if (m) { niche = m[1].trim(); location = m[2].trim(); }
  }
  if (!niche || niche.length < 2)
    return { error: 'Please tell me what to search, e.g. <code>/leads plumbers in Chicago</code>' };

  limit = Math.max(1, Math.min(Math.floor(limit) || defaultLimit, 100));
  const search = location ? niche + ' in ' + location : niche;
  return {
    search,
    request: {
      query: niche,
      location: location || null,
      limit,
      filters,
      exclude_seen: !all,
      mark_seen: true,
      enrich_emails: emails,
    },
  };
}
// ---- end shared parser ----

const allowed = String($env.TELEGRAM_ALLOWED_CHAT_IDS || '')
  .split(',').map((s) => s.trim()).filter(Boolean);
const defaultLimit = parseInt($env.DEFAULT_LEAD_LIMIT || '20', 10) || 20;
const out = [];

for (const item of $input.all()) {
  const msg = item.json.message || item.json.channel_post;
  if (!msg || typeof msg.text !== 'string') continue;

  const chatId = String(msg.chat.id);
  const fromId = msg.from ? String(msg.from.id) : '';
  // Silently ignore anyone who is not on the allow-list.
  if (allowed.length && !allowed.includes(chatId) && !allowed.includes(fromId)) continue;

  const m = msg.text.trim().match(/^\/(\w+)(?:@\w+)?\s*([\s\S]*)$/);
  if (!m) continue; // plain chat, not a command
  const cmd = m[1].toLowerCase();
  const args = m[2];

  if (['leads', 'lead', 'scrape'].includes(cmd)) {
    if (!args.trim()) { out.push({ json: { valid: false, chatId, reply: HELP } }); continue; }
    const job = parseJob(args, defaultLimit);
    if (job.error) { out.push({ json: { valid: false, chatId, reply: '⚠️ ' + job.error + '\n\n' + HELP } }); continue; }
    const who = msg.from ? (msg.from.username ? '@' + msg.from.username : msg.from.first_name) : 'channel';
    job.request.meta = { chat_id: chatId, source: 'telegram', requested_by: who };
    out.push({ json: {
      valid: true, chatId, search: job.search, request: job.request,
      ack: '🔎 Searching Google Maps for <b>' + escapeHtml(job.search) + '</b> (up to ' + job.request.limit +
           ' new leads' + (job.request.enrich_emails ? ', with email lookup' : '') + ')…\nThis usually takes 1–5 minutes.',
    } });
  } else if (['start', 'help'].includes(cmd)) {
    out.push({ json: { valid: false, chatId, reply: HELP } });
  }
}
return out;

