      mark_seen: true,
      enrich_emails: emails,
    },
  };
}
// ---- end shared parser ----

const chatId = String($env.SCHEDULE_CHAT_ID || '').trim();
if (!chatId) throw new Error('SCHEDULE_CHAT_ID is not set in .env');
const defaultLimit = parseInt($env.DEFAULT_LEAD_LIMIT || '20', 10) || 20;

// SCHEDULED_JOBS format:  niche | location | limit | flags ; niche | location ...
const lines = String($env.SCHEDULED_JOBS || '').split(';').map((s) => s.trim()).filter(Boolean);
if (!lines.length) throw new Error('SCHEDULED_JOBS is empty in .env');

return lines.map((line) => {
  const [niche = '', location = '', limit = '', flags = ''] = line.split('|').map((s) => s.trim());
  const args = niche + (location ? ' | ' + location : '') + (limit ? ' --limit ' + limit : '') + ' ' + flags;
  const job = parseJob(args, defaultLimit);
  if (job.error) {
    return { json: { valid: false, chatId, reply: '⚠️ Bad scheduled job "' + escapeHtml(line) + '": ' + job.error } };
  }
  job.request.meta = { chat_id: chatId, source: 'schedule', requested_by: 'schedule' };
  return { json: {
    valid: true, chatId, search: job.search, request: job.request,
    ack: '⏰ Scheduled run: <b>' + escapeHtml(job.search) + '</b> (up to ' + job.request.limit + ' new leads)…',
  } };
});

// Final clean / dedupe / format pass. The scraper already normalises and
// dedupes against history; this is a safety net + Telegram formatting.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const MAX_LEN = 3800; // Telegram hard limit is 4096 chars per message
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  const chatId = r.meta && r.meta.chat_id;
  if (!chatId) continue;

  const seen = new Set();
  const leads = [];
  for (const l of r.leads || []) {
    if (!l || !l.name) continue;
    const keys = [l.lead_key, l.phone_digits && 'p:' + l.phone_digits,
                  'n:' + l.name.toLowerCase().replace(/[^a-z0-9]/g, '') + '|' + (l.address || '').toLowerCase().replace(/[^a-z0-9]/g, '')]
                 .filter(Boolean);
    if (keys.some((k) => seen.has(k))) continue;
    keys.forEach((k) => seen.add(k));
    leads.push(l);
  }

  const s = r.stats || {};
  const filtered = Object.values(s.filtered || {}).reduce((a, b) => a + b, 0);
  const skipped = (s.skipped_seen || 0) + (s.skipped_duplicate || 0);
  let summary =
    '<b>📊 ' + esc(r.search) + '</b>\n' +
    '✅ <b>' + leads.length + '</b> new lead(s)\n' +
    '🔁 ' + skipped + ' already sent / duplicate\n' +
    '🧹 ' + filtered + ' filtered out\n' +
    '⏱ ' + (s.duration_s ?? '?') + 's';
  if (!leads.length) {
    summary += '\n\nNo new leads matched. Try a nearby location, loosen the filters, or add <code>--all</code>.';
  }
  out.push({ json: { chatId, text: summary } });

  let chunk = '';
  leads.forEach((l, i) => {
    const lines = ['<b>' + (i + 1) + '. ' + esc(l.name) + '</b>'];
    const info = [];
    if (l.rating != null) info.push('⭐ ' + l.rating + (l.reviews != null ? ' (' + l.reviews + ')' : ''));
    if (l.category) info.push(esc(l.category));
    if (info.length) lines.push(info.join(' · '));
    if (l.phone) lines.push('📞 <code>' + esc(l.phone) + '</code>');
    lines.push(l.website
      ? '🌐 <a href="' + esc(l.website) + '">' + esc(l.domain || l.website) + '</a>'
      : '🌐 <i>No website</i>');
    if (l.emails && l.emails.length) lines.push('✉️ ' + l.emails.map(esc).join(', '));
    if (l.address) lines.push('📍 ' + esc(l.address));
    if (l.maps_url) lines.push('🗺 <a href="' + esc(l.maps_url) + '">Open in Google Maps</a>');
    if (l.temporarily_closed) lines.push('⚠️ Temporarily closed');
    const block = lines.join('\n') + '\n\n';
    if (chunk && chunk.length + block.length > MAX_LEN) {
      out.push({ json: { chatId, text: chunk.trim() } });
      chunk = '';
    }
    chunk += block;
  });
  if (chunk.trim()) out.push({ json: { chatId, text: chunk.trim() } });
}
return out;

